  "solution": {
   "javascript": "var findKthLargest = function(nums, k) {\n    const target = nums.length - k;\n    let left = 0, right = nums.length - 1;\n    while (left <= right) {\n        const pivotIdx = left + Math.floor(Math.random() * (right - left + 1));\n        const pivot = nums[pivotIdx];\n        let less = left, current = left, greater = right;\n        while (current <= greater) {\n            if (nums[current] < pivot) {\n                [nums[less], nums[current]] = [nums[current], nums[less]];\n                less++; current++;\n            } else if (nums[current] > pivot) {\n                [nums[current], nums[greater]] = [nums[greater], nums[current]];\n                greater--;\n            } else {\n                current++;\n            }\n        }\n        if (target < less) right = less - 1;\n        else if (target > greater) left = greater + 1;\n        else return nums[target];\n    }\n};",
   "python": "import random\nfrom typing import List\n\n\nclass Solution:\n    def findKthLargest(self, nums: List[int], k: int) -> int:\n        target = len(nums) - k\n        left, right = 0, len(nums) - 1\n\n        while left <= right:\n            pivot = nums[random.randint(left, right)]\n            less = left\n            current = left\n            greater = right\n\n            while current <= greater:\n                if nums[current] < pivot:\n                    nums[less], nums[current] = nums[current], nums[less]\n                    less += 1\n                    current += 1\n                elif nums[current] > pivot:\n                    nums[current], nums[greater] = nums[greater], nums[current]\n                    greater -= 1\n                else:\n                    current += 1\n\n            if target < less:\n                right = less - 1\n            elif target > greater:\n                left = greater + 1\n            else:\n                return nums[target]\n\n        raise ValueError(\"k is outside the valid range\")\n"
  },
