  "judge": "float",
  "starter": {
   "javascript": "/**\n * @param {number[]} nums1\n * @param {number[]} nums2\n * @return {number}\n */\nvar findMedianSortedArrays = function(nums1, nums2) {\n    \n};",
   "python": "from typing import List\n\nclass Solution:\n    def findMedianSortedArrays(self, nums1: List[int], nums2: List[int]) -> float:\n        pass"
  },
  "solution": {
   "javascript": "var findMedianSortedArrays = function(nums1, nums2) {\n    if (nums1.length > nums2.length) {\n        const tmp = nums1; nums1 = nums2; nums2 = tmp;\n    }\n    const m = nums1.length, n = nums2.length;\n    const leftSize = Math.floor((m + n + 1) / 2);\n    let lo = 0, hi = m;\n    while (lo <= hi) {\n        const cut1 = Math.floor((lo + hi) / 2);\n        const cut2 = leftSize - cut1;\n        const left1 = cut1 ? nums1[cut1 - 1] : -Infinity;\n        const right1 = cut1 < m ? nums1[cut1] : Infinity;\n        const left2 = cut2 ? nums2[cut2 - 1] : -Infinity;\n        const right2 = cut2 < n ? nums2[cut2] : Infinity;\n        if (left1 <= right2 && left2 <= right1) {\n            if ((m + n) % 2) return Math.max(left1, left2);\n            return (Math.max(left1, left2) + Math.min(right1, right2)) / 2;\n        }\n        if (left1 > right2) hi = cut1 - 1;\n        else lo = cut1 + 1;\n    }\n    throw new Error('Inputs must be sorted and not both empty');\n};",
   "python": "from typing import List\n\nclass Solution:\n    def findMedianSortedArrays(self, nums1: List[int], nums2: List[int]) -> float:\n        if len(nums1) > len(nums2):\n            nums1, nums2 = nums2, nums1\n\n        m, n = len(nums1), len(nums2)\n        left_size = (m + n + 1) // 2\n        lo, hi = 0, m\n\n        while lo <= hi:\n            cut1 = (lo + hi) // 2\n            cut2 = left_size - cut1\n\n            left1 = nums1[cut1 - 1] if cut1 else float(\"-inf\")\n            right1 = nums1[cut1] if cut1 < m else float(\"inf\")\n            left2 = nums2[cut2 - 1] if cut2 else float(\"-inf\")\n            right2 = nums2[cut2] if cut2 < n else float(\"inf\")\n\n            if left1 <= right2 and left2 <= right1:\n                if (m + n) % 2:\n                    return float(max(left1, left2))\n                return (max(left1, left2) + min(right1, right2)) / 2.0\n            if left1 > right2:\n                hi = cut1 - 1\n            else:\n                lo = cut1 + 1\n\n        raise ValueError(\"Inputs must be sorted and not both empty\")"
  },
  "approach": "Binary-search the cut position in the shorter array; the cut in the other array follows from the required left-half size. A partition is valid when both left boundary values are at most the opposite right boundary values. The median then comes from the boundary maximum(s) and minimum(s). Each failed partition tells which direction to move. With m and n as the array lengths and m <= n, time is O(log m) and auxiliary space is O(1).",
