  "starter": {
   "javascript": "/**\n * @param {number[]} nums\n * @param {number} k\n * @return {number}\n */\nvar splitArray = function(nums, k) {\n    \n};",
   "python": "class Solution:\n    def splitArray(self, nums: List[int], k: int) -> int:\n        pass"
  },
  "solution": {
   "javascript": "var splitArray = function(nums, k) {\n    let low = Math.max(...nums);\n    let high = nums.reduce((a, b) => a + b, 0);\n\n    const partsNeeded = (limit) => {\n        let parts = 1, current = 0;\n        for (const value of nums) {\n            if (current + value > limit) {\n                parts += 1;\n                current = value;\n            } else {\n                current += value;\n            }\n        }\n        return parts;\n    };\n\n    while (low < high) {\n        const middle = Math.floor((low + high) / 2);\n        if (partsNeeded(middle) <= k) {\n            high = middle;\n        } else {\n            low = middle + 1;\n        }\n    }\n\n    return low;\n};",
   "python": "from typing import List\n\nclass Solution:\n    def splitArray(self, nums: List[int], k: int) -> int:\n        low, high = max(nums), sum(nums)\n\n        def parts_needed(limit: int) -> int:\n            parts = 1\n            current = 0\n            for value in nums:\n                if current + value > limit:\n                    parts += 1\n                    current = value\n                else:\n                    current += value\n            return parts\n\n        while low < high:\n            middle = (low + high) // 2\n            if parts_needed(middle) <= k:\n                high = middle\n            else:\n                low = middle + 1\n\n        return low"
  },
  "approach": "Binary search on the answer. Any candidate largest-sum limit between max(nums) and sum(nums) is feasible if a greedy left-to-right pass can cover nums using at most k parts: extend the current part until adding the next value would exceed the limit, then start a new part. Feasibility is monotone in the limit, so binary search converges on the smallest feasible limit. Time is O(n log(sum(nums)-max(nums))) and auxiliary space is O(1).",
